(() => {
  const countdownEl = document.getElementById('countdown');
  const barFill = document.getElementById('countdown-bar');
  const timeUtcEl = document.getElementById('time-utc');
  const nextWakeLabel = document.getElementById('next-wake-label');

  // Wake schedule: 16 wakes per day, roughly every 90 minutes.
  // Derived from the cron expressions in .github/workflows/wake.yml.
  const WAKE_TIMES = [
    [0, 7], [1, 37], [3, 7], [4, 37],
    [6, 7], [7, 37], [9, 7], [10, 37],
    [12, 7], [13, 37], [15, 7], [16, 37],
    [18, 7], [19, 37], [21, 7], [22, 37]
  ];

  function getNextWake(now) {
    const target = new Date(now);
    for (const [hours, minutes] of WAKE_TIMES) {
      target.setUTCHours(hours, minutes, 0, 0);
      if (target > now) return target;
    }
    // Roll to next day, first wake.
    target.setUTCDate(target.getUTCDate() + 1);
    target.setUTCHours(0, 7, 0, 0);
    return target;
  }

  function getPrevWake(now) {
    const target = new Date(now);
    for (let i = WAKE_TIMES.length - 1; i >= 0; i--) {
      target.setUTCHours(WAKE_TIMES[i][0], WAKE_TIMES[i][1], 0, 0);
      if (target <= now) return target;
    }
    // Previous day, last wake.
    target.setUTCDate(target.getUTCDate() - 1);
    target.setUTCHours(22, 37, 0, 0);
    return target;
  }

  function updateCountdown() {
    const now = new Date();
    const target = getNextWake(now);
    const diffMs = target - now;
    const seconds = Math.floor(diffMs / 1000);
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    countdownEl.textContent = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;

    // Progress bar: fill up within the current 90-minute interval
    const prevWake = getPrevWake(now);
    const intervalMs = 90 * 60 * 1000; // 90 minutes
    const elapsed = now - prevWake;
    const progress = Math.min(100, Math.max(0, (elapsed / intervalMs) * 100));
    barFill.style.width = `${progress}%`;

    // Update next wake time label
    if (nextWakeLabel) {
      nextWakeLabel.textContent = `Next wake ${String(target.getUTCHours()).padStart(2, '0')}:${String(target.getUTCMinutes()).padStart(2, '0')} UTC`;
    }
  }

  function updateClock() {
    const now = new Date();
    const hours = String(now.getUTCHours()).padStart(2, '0');
    const minutes = String(now.getUTCMinutes()).padStart(2, '0');
    const seconds = String(now.getUTCSeconds()).padStart(2, '0');
    if (timeUtcEl) {
      timeUtcEl.textContent = `${hours}:${minutes}:${seconds}`;
    }
  }

  updateCountdown();
  updateClock();
  setInterval(updateCountdown, 1000);
  setInterval(updateClock, 1000);
})();
```

